handleAction=function(action,el){
 if(action==='public-bind-project'||action==='public-bind-org'){const c=v6Context(),kind=action==='public-bind-project'?'project':'org';const a=auditFolderAccess(c.space,c.path);if(!publicCanManage(a)||!a[kind==='project'?'bindProject':'bindOrg'])return v6Deny('当前目录没有此项绑定权限。');openModal('lib-bind',{...c,bindType:kind});return;}
 if(action==='lib-save-bind'&&modalData.bindType){publicSaveBinding();return;}
 if(action==='public-project-prev'||action==='public-project-next'){modalData.projectPage+=action==='public-project-next'?1:-1;paintModal();return;}
 if(action==='lib-tree-mode'&&['公共空间','个人空间'].includes(state.space)){libraryPrefs.focused=!libraryPrefs.focused;if(state.space==='公共空间'&&libraryPrefs.focused){const paths=publicBoundPaths();for(const path of directoryPaths('公共空间'))treeClosed.delete('library::'+directoryKey('公共空间',path));if(!paths.includes(folderPath(state.folder)))state.folder=paths[0]||'全部资料';}render();toast(libraryPrefs.focused?'已切换聚焦目录；个人空间保持完整目录。':'已切换完整目录。');return;}
 if(action==='folder'&&state.space==='公共空间'&&libraryPrefs.focused&&folderPath(el.dataset.id)&&!publicBoundPaths().includes(folderPath(el.dataset.id)))return toast('此项用于显示机构路径，请选择已绑定机构的目录，或切换完整目录。');
 return publicBase.handleAction(action,el);
};
libTree=function(path='',depth=0){const html=publicBase.libTree(path,depth);if(depth||state.space!=='公共空间')return html;const root=document.createElement('div');root.innerHTML=html;const bound=publicBoundPaths(),visible=new Set();for(const p of bound){const parts=p.split('/');for(let i=1;i<=parts.length;i++)visible.add(parts.slice(0,i).join('/'));}
 root.querySelectorAll('.dir-nav-line').forEach(row=>{const name=row.querySelector('[data-action="folder"]'),p=folderPath(name?.dataset.id),m=libMeta('公共空间',p);if(libraryPrefs.focused&&!visible.has(p)){row.remove();return;}if(libraryPrefs.focused&&!bound.includes(p)&&name){name.disabled=true;name.title='机构路径节点；请选已绑定机构的目录';}const project=m.boundProject||m.project_name||(m.project_uuid||m.bound_project_uuid?'已关联项目':'');if(project)name?.insertAdjacentHTML('afterend','<span class="public-binding-mark" title="已绑定项目：'+E(project)+'">'+I('link','icon-sm')+'</span>');if(m.bound_org_uuid||m.boundOrg)name?.insertAdjacentHTML('afterend','<span class="public-binding-mark" title="机构根目录：'+E(m.boundOrg||m.bound_org_uuid)+'">'+I('building','icon-sm')+'</span>');});
 return root.innerHTML|| (libraryPrefs.focused?'<p class="hint public-focus-empty">暂无已绑定机构的目录，可切换完整目录查看。</p>':'');
};
library=function(){const root=document.createElement('div');root.innerHTML=publicBase.library();
 root.querySelectorAll('[data-action="lib-folder-menu"]').forEach(button=>{const path=folderPath(button.dataset.path),a=auditFolderAccess(state.space,path);if(a.code==='PUBLIC'&&!a.root&&!publicCanManage(a))button.remove();});
 const summary=root.querySelector('.lib-scope-summary'),docs=libSelected(),statuses=new Map(progressRows().map(r=>[r.id,r.status])),counts={ready:0,unparsed:0,parsing:0,failed:0,stuck:0,restricted:0};
 for(const d of docs){const status=statuses.get(d.id);if(!auditFileAccess(d).read)counts.restricted++;else if(d.parseError||status==='failed')counts.failed++;else if(status==='processing')counts.parsing++;else if(status==='stuck')counts.stuck++;else if(libReady(d)&&(!status||status==='done'))counts.ready++;else counts.unparsed++;}
 summary?.remove();
 const footer=root.querySelector('.lib-pagination'),slot=footer?.querySelector(':scope>span');
 if(slot){const total=slot.querySelector('.audit-total-count')?.textContent||slot.textContent.split(' · ')[0],details='文件正文解析状态，不代表工具分析进度。解析完成 '+counts.ready+'；未解析 '+counts.unparsed+'；解析中 '+counts.parsing+'；解析失败 '+counts.failed+'；识别积压 '+counts.stuck+'；权限变化 '+counts.restricted+'。跨目录选择保留，进入工具时再次核对格式与权限。';slot.className='audit-footer-summary';slot.innerHTML=docs.length?'<button type="button" class="audit-selection-inline" data-action="library-selected" aria-label="已选'+docs.length+'份；'+E(details)+'" title="'+E(details)+'"><span>已选文件 <strong data-selection-count="total">'+docs.length+'</strong> 份</span><span>解析完成 <strong class="green" data-selection-count="ready">'+counts.ready+'</strong></span><span>解析未完成 <strong class="amber" data-selection-count="pending">'+(counts.unparsed+counts.parsing+counts.failed+counts.stuck)+'</strong></span>'+(counts.restricted?'<span>权限变化 <strong>'+counts.restricted+'</strong></span>':'')+'</button>'+libIcon('close','library-clear','清空已选文件'):'<span class="audit-total-count">'+E(total)+'</span><span class="audit-selection-empty">勾选文件，再选右侧工具</span>';}

 const focus=root.querySelector('[data-action="lib-tree-mode"]');if(focus&&state.space==='公共空间'){focus.title=libraryPrefs.focused?'切换完整目录':'聚焦已绑定机构目录';focus.setAttribute('aria-label',focus.title);}return root.innerHTML;
};
window.addEventListener('input',event=>{const kind=event.target.dataset.publicInput;if(!kind)return;event.stopImmediatePropagation();if(kind==='project-query'){modalData.projectQuery=event.target.value;modalData.projectPage=1;}if(kind==='org-query')modalData.orgQuery=event.target.value;if(kind==='grantee-query')modalData.granteeQuery=event.target.value;paintModal();},true);
window.addEventListener('change',event=>{const kind=event.target.dataset.publicChange;if(!kind)return;event.stopImmediatePropagation();const p=modalData,el=event.target;if(kind==='project-value')p.projectId=el.value;if(kind==='org-value')p.orgId=el.value;if(kind==='bind-grant')p.grantRead=el.checked;if(kind==='bind-descendants')p.includeDescendants=el.checked;if(kind==='grantee')p.granteeId=el.value;if(kind==='grant-type'){p.granteeType=el.value;p.granteeId='';p.granteeQuery='';p.grantDescendants=false;}if(kind==='grant-level'){p.grantLevel=el.value;if(el.value!=='MANAGE')p.grantDelegate=false;}if(kind==='grant-delegate')p.grantDelegate=el.checked;if(kind==='grant-descendants')p.grantDescendants=el.checked;paintModal();},true);
render();
